    /** 当前行变化 */
    currentRowChanged: [currentRow: DataRow | null, originatorId?: string];
    /** 选中行变化 */
    selectedRowsChanged: [selectedRows: DataRow[], originatorId?: string];
    /** 行数据批量变化（防抖 16ms） */
    rowsChanged: [];
    /** 编辑态字段变化 */
